INSERT INTO `Questions` (`id`, `type`, `question`, `solution`, `hint`, `feedback`, `difficulty`, `assets`, `extraData`, `duration`, `active`) VALUES
(1,	'text',	'Dans la salle 126, une étiquette dissimulée attend. Votre quête commence en entrant, mais votre regard doit se tourner vers la machine adjacente à la sortie.',	'IUT1I-126-W15',	'Cherchez à proximité des portes de sortie.',	'{\"correct\": \"Bravo, vous avez trouvé le code caché !\", \"incorrect\": \"Ce n\'est pas le bon code, persévérez.\"}',	'moyen',	NULL,	NULL,	180,	0),
(2,	'text',	'Trouvez les deux nombres dont les carrés respectifs donnent 9 et 16, additionnez-les et multipliez le résultat par le nombre d\'œuvre dans une Heptalogie.',	'49',	'Hepta... c\'est 7',	'{\"correct\": \"Calcul exact ! Vous avez déverrouillé l\'indice.\", \"incorrect\": \"C\'est niveau collège là quand même.\"}',	'moyen',	NULL,	NULL,	180,	1),
(3,	'action',	'Vous allez voir 4 images, retenez le plus d\'informations possibles en 5 secondes.',	'jaune',	NULL,	'{\"correct\": \"Votre mémoire est impressionnante !\", \"incorrect\": \"Ce n\'est pas la bonne réponse.\"}',	'moyen',	'[\"4_images_enigma.png\"]',	'memory_images.js',	60,	1),
(4,	'text',	'Dans un cadre sur la porte des salles contenant des ordinateurs, deux consonnes se répètent. Trouvez-les et insérez la 5ᵉ voyelle de l’alphabet entre elles.',	'LUL',	'Observez bien le cadre, les lettres vous appellent.',	'{\"correct\": \"Bravo, vous avez découvert le mot !\", \"incorrect\": \"Ce n\'est pas ça, perdez espoir.\"}',	'moyen',	NULL,	NULL,	120,	0),
(5,	'comparison',	'Comparez ces deux photos. Identifiez l’élément manquant ou ajouté.',	'chaise',	'Regardez attentivement chaque détail.',	'{\"correct\": \"Bien vu, c\'était la chaise !\", \"incorrect\": \"Non, ce n\'est pas l\'intrus.\"}',	'facile',	'[\"photo1.jpg\", \"photo2.jpg\"]',	NULL,	90,	0),
(6,	'action',	'Votre téléphone clignote en morse. Décodez le message et saisissez-le.',	'SOS',	'Le morse a sa propre musique. Écoutez les rythmes longs et courts.',	'{\"correct\": \"Vous avez correctement décodé le message !\", \"incorrect\": \"Ce n\'est pas la bonne traduction.\"}',	'moyen',	'[\"morse_chart.jpg\"]',	'morse_flash.js',	150,	0),
(7,	'audio',	'Trois extraits musicaux se superposent. Retrouvez les trois titres.',	'Imagine,Rouge,Believer',	'Écoutez attentivement chaque mélodie.',	'{\"correct\": \"Excellente oreille musicale !\", \"incorrect\": \"Ce n\'est pas ça, essayez à nouveau.\"}',	'difficile',	'[\"track1.mp3\", \"track2.mp3\", \"track3.mp3\"]',	NULL,	180,	0),
(8,	'text',	'Trouvez le nombre manquant dans la suite : 1, 1, 2, 3, 5, 8, ?',	'13',	'C\'est une suite bien connue des mathématiciens.',	'{\"correct\": \"C\'est juste, c\'est la suite de Fibonacci !\", \"incorrect\": \"Non, ce n\'est pas le bon nombre.\"}',	'moyen',	NULL,	NULL,	60,	0),
(9,	'action',	'Amenez la balle virtuelle jusqu’à la ligne d’arrivée sans heurter les obstacles.',	'success',	NULL,	'{\"correct\": \"Vous avez franchi la ligne d\'arrivée !\", \"incorrect\": \"La balle a touché un obstacle, réessayez.\"}',	'moyen',	NULL,	'game_balance.js',	120,	0),
(10,	'memory',	'Une série d\'images s\'affiche. Quelle était la couleur dominante de la quatrième image ?',	'bleu',	NULL,	'{\"correct\": \"Votre mémoire est impressionnante !\", \"incorrect\": \"Ce n\'est pas la bonne réponse.\"}',	'moyen',	'[\"img5.jpg\", \"img6.jpg\", \"img7.jpg\", \"img8.jpg\"]',	NULL,	60,	0),
(11,	'code',	'Scannez ce QR Code dissimulé dans la salle 126. Il vous révélera un chiffre essentiel.',	'112',	'Y\'a qu\'un seul QR code abusez pas.',	'{\"correct\": \"Vous avez trouvé le bon chiffre !\", \"incorrect\": \"Ce n\'est pas la bonne réponse, scannez à nouveau.\"}',	'facile',	NULL,	NULL,	120,	0),
(12,	'interaction',	'Inclinez votre téléphone pour déplacer une bille à travers un labyrinthe et atteindre la sortie.',	'success',	NULL,	'{\"correct\": \"Bravo, vous avez traversé le labyrinthe !\", \"incorrect\": \"Essayez encore, vous y êtes presque.\"}',	'moyen',	'maze_bg.png',	'maze_game.js',	180,	0),
(13,	'speed',	'Un code s’affiche pendant une seconde. Tapez-le rapidement.',	'847312',	'Soyez prêt, le code disparaît vite.',	'{\"correct\": \"Vous avez saisi le code à temps !\", \"incorrect\": \"Trop lent.\"}',	'difficile',	NULL,	'speed_code.js',	30,	0),
