(18,	'gesture',	'Reproduis cette série de mouvements : haut, bas, gauche, droite. Suis bien l\'ordre !',	'haut-bas-gauche-droite',	'Concentre-toi sur les mouvements indiqués.',	'{\"correct\": \"Série de mouvements réussie !\", \"incorrect\": \"Ce n\'est pas tout à fait ça, essaie encore.\"}',	'moyen',	NULL,	NULL,	90,	0),
