(189,	'text',	'Je commence la nuit et je termine le matin. Qui suis-je ?',	'N',	'C\'est une lettre.',	'{\"correct\": \"Bravo, vous avez trouvé la bonne réponse !\", \"incorrect\": \"Perdu.\"}',	'moyen',	NULL,	NULL,	30,	1),
(190,	'text',	'Qu’est-ce qui a une tête, un pied, mais pas de jambes ?',	'Lit',	'Un objet du quotidien.',	'{\"correct\": \"Bravo, vous avez trouvé la bonne réponse !\", \"incorrect\": \"Perdu.\"}',	'facile',	NULL,	NULL,	60,	1),
