(192,	'text',	'2 + 2 = ?',	'6',	'Méfie toi.',	'{\"correct\": \"Bravo, vous avez trouvé la bonne réponse!\", \"incorrect\": \"La réponse était 6. Explication : 2 + 2 = 4. Mais il y a deux \'2\', donc 4 + 2 = 6.\"}',	'difficile',	NULL,	NULL,	200,	1),
