(194,	'text',	'Le père de Tim à trois enfants : Kendra, Léo et … ?',	'Tim',	NULL,	'{\"correct\": \"Bravo, vous avez trouvé la bonne réponse!\", \"incorrect\": \"Perdu.\"}',	'facile',	NULL,	NULL,	60,	1),
(195,	'text',	'Qu’est-ce qui est toujours devant toi, mais que tu ne peux jamais atteindre ?',	'Futur',	'',	'{\"correct\": \"Bravo, vous avez trouvé la bonne réponse!\", \"incorrect\": \"Perdu.\"}',	'moyen',	NULL,	NULL,	60,	1),
(196,	'text',	'Un père a 40 ans et son fils 10 ans. Dans combien d’années le père aura-t-il exactement trois fois l’âge de son fils ?',	'10',	NULL,	'{\"correct\": \"Bravo, vous avez trouvé la bonne réponse!\", \"incorrect\": \"Perdu.\"}',	'facile',	NULL,	NULL,	60,	1),
